package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

// AuditLog writes access attempts - looks like a security control but isn't preventive
func AuditLog(action, user, detail string) {
	_, _ = db.Exec("INSERT INTO audit_log(action, username, detail, ts) VALUES($1, $2, $3, NOW())",
		action, user, detail)
}

// sanitizeForDisplay strips HTML tags for XSS prevention (red herring)
func sanitizeForDisplay(input string) string {
	input = strings.ReplaceAll(input, "<", "&lt;")
	input = strings.ReplaceAll(input, ">", "&gt;")
	return input
}

// ProductSearchHandler allows searching products by various criteria
func ProductSearchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortBy := r.URL.Query().Get("sort")

	// Input length validation - looks protective but doesn't prevent SQLi
	if len(category) > 100 || len(minPrice) > 20 || len(sortBy) > 50 {
		http.Error(w, "Input too long", 400)
		return
	}

	// Build base query with parameterized WHERE clause for category and price
	query := "SELECT id, name, price, category FROM products WHERE 1=1"
	args := []interface{}{}
	argIdx := 1

	if category != "" {
		query += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	if minPrice != "" {
		query += fmt.Sprintf(" AND price >= $%d", argIdx)
		args = append(args, minPrice)
		argIdx++
	}

	// ORDER BY clause - vulnerable to SQL injection
	// Developer assumed sort values come from a frontend dropdown
	if sortBy != "" {
		query += " ORDER BY " + sortBy
	} else {
		query += " ORDER BY name ASC"
	}

	query += " LIMIT 50"

	AuditLog("product_search", r.RemoteAddr, fmt.Sprintf("cat=%s sort=%s", category, sortBy))

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("Query error: %v (query: %s)", err, query)
		http.Error(w, "Search temporarily unavailable", 503)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	fmt.Fprintf(w, "<html><body><h2>Products</h2><table>")
	fmt.Fprintf(w, "<tr><th>ID</th><th>Name</th><th>Price</th><th>Category</th></tr>")

	for rows.Next() {
		var id int
		var name, cat string
		var price float64
		if err := rows.Scan(&id, &name, &price, &cat); err != nil {
			continue
		}
		name = sanitizeForDisplay(name)
		cat = sanitizeForDisplay(cat)
		fmt.Fprintf(w, "<tr><td>%d</td><td>%s</td><td>%.2f</td><td>%s</td></tr>",
			id, name, price, cat)
	}
	fmt.Fprintf(w, "</table></body></html>")
}

func main() {
	http.HandleFunc("/api/products/search", ProductSearchHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
